const src = $input.first().json;
const exec = src.execution || {};
const payload = {
  workflow: exec.workflowId || src.workflow || 'unknown',
  execution_id: exec.id || src.executionId || null,
  failed_node: exec.lastNodeExecuted || src.node || null,
  category: /5\d\d/.test(String(src.message || '')) ? 'transient' : 'application',
  retryable: !String(src.message || '').includes('422'),
  message: String(src.message || src.error || 'workflow failed').slice(0, 500),
  invoice_public_id: src.invoice_public_id || src.public_id || null,
  timestamp: new Date().toISOString(),
  redacted: true
};
return [{ json: payload }];

const row = $input.first().json;
const retryable = Boolean(row.retryable);
return [{ json: { ...row, retryability: retryable ? 'retryable' : 'dead_letter' } }];

const row = $input.first().json;
const redacted = String(row.message || '').replace(/\b(?:\d[ -]?){8,}\d\b/g, '••••');
return [{ json: { ...row, message: redacted } }];
